       VALUES ($1, $2, $2)
       RETURNING id, user_id, original_total_satang, grand_total_satang`,
      [userId, original_total_satang]
    );

    return res.status(201).json(result.rows[0]);
  } catch (err) {
    return next(err);
  }
}

/**
 * GET /api/orders/:id
